#include <iostream>

class Date {
public:
    explicit Date(int m = 1, int d = 1, int y = 2000)
        : month(m), day(d), year(y) {}

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

private:
    int month;
    int day;
    int year;
};

int main() {
    Date date1(7, 4, 2004);
    Date date2; // Defaults to 1/1/2000

    std::cout << "date1 = ";
    date1.print();
    std::cout << "\ndate2 = ";
    date2.print();

    date2 = date1; // Default memberwise assignment

    std::cout << "\n\nAfter default memberwise assignment, date2 = ";
    date2.print();
    std::cout << std::endl;

    return 0;
}

#include <iostream>

class Time {
public:
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec); // Non-const function invoked inside constructor
    }

    void setTime(int hr, int min, int sec) {
        hour = hr;
        minute = min;
        second = sec;
    }

    void setHour(int hr) {
        hour = hr;
    }

    int getHour() const {
        return hour;
    }

    int getMinute() const {
        return minute;
    }

    void printUniversal() const {
        std::cout << (hour < 10 ? "0" : "") << hour << ':'
                  << (minute < 10 ? "0" : "") << minute << ':'
                  << (second < 10 ? "0" : "") << second;
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    Time wakeUp(6, 45, 0);       // Non-const object
    const Time noon(12, 0, 0);   // Const object

    // 1. Non-const object calling non-const function: OK
    wakeUp.setHour(18);

    // 2. Non-const object calling const function: OK
    std::cout << "wakeUp hour: " << wakeUp.getHour() << '\n';

    // 3. Const object calling const function: OK
    std::cout << "noon universal: ";
    noon.printUniversal();
    std::cout << '\n';

    // 4. Const object calling non-const function: COMPILATION ERROR
    // noon.setHour(12); // Error: cannot convert 'this' from 'const Time*' to 'Time*'

    return 0;
}

#include <iostream>
#include <string>

class Date {
public:
    explicit Date(int m = 1, int d = 1, int y = 1900)
        : month(m), day(d), year(y) {
        std::cout << "Date constructor: " << month << '/' << day << '/' << year << '\n';
    }

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

    ~Date() {
        std::cout << "Date destructor: ";
        print();
        std::cout << '\n';
    }

private:
    int month;
    int day;
    int year;
};

class Employee {
public:
    Employee(const std::string& first, const std::string& last,
             const Date& dateOfBirth, const Date& dateOfHire)
        : firstName(first),
          lastName(last),
          birthDate(dateOfBirth), // Initialized in declaration order
          hireDate(dateOfHire) {
        std::cout << "Employee constructor: " << firstName << ' ' << lastName << '\n';
    }

    void print() const {
        std::cout << lastName << ", " << firstName << " Hired: ";
        hireDate.print();
        std::cout << " Birthday: ";
        birthDate.print();
        std::cout << '\n';
    }

    ~Employee() {
        std::cout << "Employee destructor: " << firstName << ' ' << lastName << '\n';
    }

private:
    std::string firstName;
    std::string lastName;
    const Date birthDate;
    const Date hireDate;
};

int main() {
    {
        Date birth(7, 24, 1985);
        Date hire(3, 12, 2010);

        std::cout << "-- Constructing Employee --\n";
        Employee manager("Grace", "Hopper", birth, hire);
        std::cout << "-- Employee Profile --\n";
        manager.print();
        std::cout << "-- Exiting scope --\n";
    }
    return 0;
}
